import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // 读取 n 和数组
        int n = sc.nextInt();
        int[] a = new int[n];
        for(int i = 0; i < n; i++){
            a[i] = sc.nextInt();
        }

        // 生成 2~100 范围内所有素数
        List<Integer> primes = new ArrayList<>();
        for(int x = 2; x <= 100; x++){
            boolean isP = true;
            for(int d = 2; d*d <= x; d++){
                if(x % d == 0){ isP = false; break; }
            }
            if(isP) primes.add(x);
        }

        int P = primes.size();
        int[] mask = new int[n]; // mask[i] 存放 a[i] 的质因子奇偶掩码

        // 计算掩码
        for(int i = 0; i < n; i++){
            int v = a[i];
            for(int j = 0; j < P; j++){
                int cnt = 0;
                while(v % primes.get(j) == 0){
                    v /= primes.get(j);
                    cnt ^= 1;
                }
                if(cnt == 1){
                    mask[i] |= (1 << j);
                }
            }
        }

        long ans = 0;
        int total = 1 << n;
        // 枚举子集
        for(int bm = 1; bm < total; bm++){
            int x = 0;
            for(int i = 0; i < n; i++){
                if((bm & (1 << i)) != 0){
                    x ^= mask[i];
                }
            }
            if(x == 0) ans++;
        }

        System.out.println(ans);
    }
}
